(17, 3, 'Brushed Italian Suede Penny Loafers', 'italian-suede-penny-loafers', 245.00, 290.00, 'Hand-sewn moccasin construction in rich snuff suede with leather soles and memory foam insoles for unrivaled comfort.', '["EU 40","EU 41","EU 42","EU 43","EU 44"]', '["Parisian Amber","Monochrome Black"]', '{"Parisian Amber":"https:\/\/images.unsplash.com\/photo-1533867617858-e7b97e060509?auto=format&fit=crop&w=800&q=80"}', 'https://images.unsplash.com/photo-1533867617858-e7b97e060509?auto=format&fit=crop&w=800&q=80', '["https:\/\/images.unsplash.com\/photo-1533867617858-e7b97e060509?auto=format&fit=crop&w=800&q=80"]', TRUE, FALSE, 22, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
(18, 3, 'Chelsea Boots in Waxed Nero Suede', 'chelsea-boots-waxed-nero-suede', 265.00, NULL, 'Sleek almond-toe Chelsea boots crafted from weatherproof waxed Italian suede with tonal elastic side gussets.', '["EU 40","EU 41","EU 42","EU 43","EU 44"]', '["Monochrome Black"]', '{"Monochrome Black":"https:\/\/images.unsplash.com\/photo-1638247025967-b4e38f787b76?auto=format&fit=crop&w=800&q=80"}', 'https://images.unsplash.com/photo-1638247025967-b4e38f787b76?auto=format&fit=crop&w=800&q=80', '["https:\/\/images.unsplash.com\/photo-1638247025967-b4e38f787b76?auto=format&fit=crop&w=800&q=80"]', FALSE, TRUE, 18, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
(19, 4, 'Double-Breasted Cashmere Blend Overcoat', 'double-breasted-cashmere-overcoat', 450.00, 520.00, 'Magnificent heavy-drape double-breasted coat in 90% virgin wool and 10% Mongolian cashmere with horn button fastening.', '["S","M","L","XL"]', '["Monochrome Black","Charcoal Grey"]', '{"Monochrome Black":"https:\/\/images.unsplash.com\/photo-1544923246-77307dd654cb?auto=format&fit=crop&w=800&q=80"}', 'https://images.unsplash.com/photo-1544923246-77307dd654cb?auto=format&fit=crop&w=800&q=80', '["https:\/\/images.unsplash.com\/photo-1544923246-77307dd654cb?auto=format&fit=crop&w=800&q=80"]', TRUE, TRUE, 15, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
(20, 4, 'Minimalist Wool Tailored Blazer', 'minimalist-wool-tailored-blazer', 340.00, NULL, 'Single-breasted unstructured blazer crafted from lightweight tropical wool with canvassed lapels and natural shoulders.', '["S","M","L","XL"]', '["Monochrome Black","Navy Blue"]', '{"Monochrome Black":"https:\/\/images.unsplash.com\/photo-1507679799987-c73779587ccf?auto=format&fit=crop&w=800&q=80"}', 'https://images.unsplash.com/photo-1507679799987-c73779587ccf?auto=format&fit=crop&w=800&q=80', '["https:\/\/images.unsplash.com\/photo-1507679799987-c73779587ccf?auto=format&fit=crop&w=800&q=80"]', TRUE, FALSE, 20, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
(21, 4, 'Full-Grain Lambskin Leather Moto Jacket', 'lambskin-leather-moto-jacket', 490.00, 580.00, 'Supple full-grain Italian nappa lambskin jacket featuring custom brushed gunmetal hardware and silky cupro lining.', '["S","M","L","XL"]', '["Monochrome Black"]', '{"Monochrome Black":"https:\/\/images.unsplash.com\/photo-1551028719-00167b16eac5?auto=format&fit=crop&w=800&q=80"}', 'https://images.unsplash.com/photo-1551028719-00167b16eac5?auto=format&fit=crop&w=800&q=80', '["https:\/\/images.unsplash.com\/photo-1551028719-00167b16eac5?auto=format&fit=crop&w=800&q=80"]', TRUE, TRUE, 12, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
(22, 5, 'Pleated Wide-Leg Wool Flannel Trousers', 'pleated-wide-leg-wool-trousers', 160.00, 195.00, 'Double forward pleats, extended tab waistband with side adjusters, cut from fluid winter wool flannel.', '["S","M","L","XL"]', '["Charcoal Grey","Monochrome Black"]', '{"Charcoal Grey":"https:\/\/images.unsplash.com\/photo-1624378439575-d8705ad7ae80?auto=format&fit=crop&w=800&q=80"}', 'https://images.unsplash.com/photo-1624378439575-d8705ad7ae80?auto=format&fit=crop&w=800&q=80', '["https:\/\/images.unsplash.com\/photo-1624378439575-d8705ad7ae80?auto=format&fit=crop&w=800&q=80"]', FALSE, TRUE, 32, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
(23, 6, 'Alexandre Monogram Leather Weekender Duffel', 'alexandre-monogram-leather-weekender', 380.00, 450.00, 'Generous travel duffel crafted from scratch-resistant saffiano calf leather with detachable strap and padlock.', '["One Size"]', '["Monochrome Black"]', '{"Monochrome Black":"https:\/\/images.unsplash.com\/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=800&q=80"}', 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=800&q=80', '["https:\/\/images.unsplash.com\/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=800&q=80"]', TRUE, TRUE, 16, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
(24, 6, 'Minimalist Matte Black Chronograph Timepiece', 'minimalist-matte-black-chronograph', 310.00, 360.00, '40mm sapphire crystal dial with Swiss quartz chronograph movement, 5ATM water resistance, and Milanese mesh band.', '["40mm"]', '["Monochrome Black"]', '{"Monochrome Black":"https:\/\/images.unsplash.com\/photo-1524805444758-089113d48a6d?auto=format&fit=crop&w=800&q=80"}', 'https://images.unsplash.com/photo-1524805444758-089113d48a6d?auto=format&fit=crop&w=800&q=80', '["https:\/\/images.unsplash.com\/photo-1524805444758-089113d48a6d?auto=format&fit=crop&w=800&q=80"]', TRUE, FALSE, 24, '2026-01-01 00:00:00', '2026-01-01 00:00:00');
