INSERT INTO reviews (id, product_id, user_name, rating, comment, created_at, updated_at) VALUES
(1, 1, 'Sophia Laurent', 5, 'Exquisite Mulberry silk. The drape and sheen under evening lighting are immaculate. Worth every single cent.', '2026-10-15 10:00:00', '2026-10-15 10:00:00'),
(2, 1, 'Julian Vance', 5, 'Masterpiece tailoring. Mother-of-pearl buttons are beautifully secured. Delivered in less than 25 minutes to Rosewood.', '2026-10-18 14:20:00', '2026-10-18 14:20:00'),
(3, 1, 'Elena Rostova', 4, 'Very luxurious feel. Slightly slim around the forearms, so recommend sizing up if you prefer a relaxed silhouette.', '2026-10-22 18:35:00', '2026-10-22 18:35:00'),
(4, 2, 'Marcus Sterling', 5, 'The crisp collar stance is unmatched. Holds its shape effortlessly throughout 12-hour boardroom meetings.', '2026-10-10 09:15:00', '2026-10-10 09:15:00'),
(5, 2, 'Dara Samnang', 5, 'Best dress shirt in Cambodia. Breathable two-ply weave keeps you fresh even in Phnom Penh tropical humidity.', '2026-10-14 11:30:00', '2026-10-14 11:30:00'),
(6, 3, 'Channary Meas', 5, 'The French linen texture is extraordinarily refined. Beautiful subtle slub without looking wrinkled.', '2026-10-12 16:40:00', '2026-10-12 16:40:00'),
(7, 3, 'Alexandre Client', 4, 'Perfect vacation resort piece. Wore it in Kep over the weekend, received endless compliments.', '2026-10-19 20:10:00', '2026-10-19 20:10:00'),
(8, 4, 'Elena Rostova', 5, 'Dramatic fluid drape. The Japanese satin catches subtle ambient reflections beautifully in dark lounges.', '2026-10-08 21:00:00', '2026-10-08 21:00:00'),
(9, 7, 'Dara Samnang', 5, 'The 300 GSM weight creates the perfect structured boxy drop. Collar never sags after washing. Gold standard.', '2026-10-16 13:25:00', '2026-10-16 13:25:00'),
(10, 7, 'Julian Vance', 5, 'I bought 5 of these as my daily uniform. Highest quality luxury blank tee on the market.', '2026-10-21 15:40:00', '2026-10-21 15:40:00'),
(11, 8, 'Sophia Laurent', 5, 'Silky soft against sensitive skin. Completely opaque so no undershirt is needed. Pure perfection.', '2026-10-05 10:50:00', '2026-10-05 10:50:00'),
(12, 13, 'Alexandre Client', 5, 'Comparable to top Milan fashion houses. The full-grain calfskin leather is butter-soft with zero break-in period.', '2026-10-20 12:15:00', '2026-10-20 12:15:00'),
(13, 13, 'Marcus Sterling', 5, 'Margom sole provides supreme cushioning. Gold foil numbering on the heel is understated yet elite.', '2026-10-24 17:30:00', '2026-10-24 17:30:00'),
(14, 14, 'Dara Samnang', 5, 'Futuristic silhouette with unbelievable comfort. The multi-density EVA sole makes walking 10km effortless.', '2026-10-26 14:05:00', '2026-10-26 14:05:00'),
(15, 15, 'Julian Vance', 5, 'True Goodyear welt craftsmanship. The hand-burnished mirror shine on the toe box is sensational.', '2026-10-11 08:45:00', '2026-10-11 08:45:00'),
(16, 17, 'Sophia Laurent', 5, 'The snuff suede shade is sublime. Pairs effortlessly with white linen trousers or dark denim.', '2026-10-17 19:20:00', '2026-10-17 19:20:00'),
(17, 19, 'Julian Vance', 5, 'The cashmere blend is heavy, warm, and moves with majestic regal elegance. A true heirloom piece.', '2026-10-23 11:10:00', '2026-10-23 11:10:00'),
(18, 21, 'Alexandre Client', 5, 'The lambskin nappa is buttery soft and the custom gunmetal zippers glide like butter. Elite outerwear.', '2026-10-27 16:55:00', '2026-10-27 16:55:00'),
(19, 23, 'Marcus Sterling', 5, 'The ultimate travel companion. Fits overhead cabins easily, and the saffiano leather resists all scuffs.', '2026-10-13 18:00:00', '2026-10-13 18:00:00'),
(20, 24, 'Channary Meas', 5, 'Subtle, understated, and commanding. The stealth matte black finish turns heads everywhere.', '2026-10-25 10:30:00', '2026-10-25 10:30:00');
